import{gateMasks,validateGateMasks}from'./gate-cells.js';
import{spriteId}from'./sprite-workbench.js';
export function gateEditor(api){
 const $=s=>document.querySelector(s),esc=api.esc;
 async function imageAsset(id){const a=api.asset(id);if(!a)throw Error('Gate artwork is missing.');return await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Gate artwork could not be opened.'));im.src=a.data||a.src;});}
 function open(style=null,placed=null){if(style){edit(style,placed).catch(api.error);return;}api.modal('Make a custom gate',`<p>Choose a fence gate as a starting point, or use the tiles currently selected in the palette. You can mark exactly which cells open and where A interacts.</p><label>Fence style<select id="gateSourceStyle">${api.styles().map(g=>`<option value="${esc(g.id)}">${esc(g.name)} · ${g.w} × ${g.h}</option>`).join('')}</select></label><div class="smart-actions"><button id="gateUseStyle" type="button" class="primary">Customize this fence</button><button id="gateUseSelected" type="button">Use selected tiles</button></div>`);$('#gateUseStyle').onclick=()=>edit(api.styles().find(g=>g.id===$('#gateSourceStyle').value)).catch(api.error);$('#gateUseSelected').onclick=async()=>{try{const c=await api.captureSelection(),im=c.image;if(im.width%16||im.height%16||im.width>128||im.height>128)throw Error('Select between 1 × 1 and 8 × 8 tiles.');const canvas=document.createElement('canvas');canvas.width=im.width;canvas.height=im.height;canvas.getContext('2d').putImageData(im,0,0);await edit({name:'My fence gate',w:im.width/16,h:im.height/16},null,canvas);}catch(e){api.error(e);}};}
 async function edit(source,placed=null,provided=null){
 const closed=document.createElement('canvas');closed.width=source.w*16;closed.height=source.h*16;const ctx=closed.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(provided||await imageAsset(source.closedAssetId),0,0,closed.width,closed.height);const masks=gateMasks(source),draft={...structuredClone(source),id:placed?source.id:api.library.has('gateStyles',source.id)?source.id:spriteId(),closedMask:structuredClone(masks.closed),openMask:structuredClone(masks.open),interactionMask:source.interactionMask?structuredClone(source.interactionMask):Array.from({length:source.h},(_,y)=>Array(source.w).fill(y===source.h-1?1:0)),behindMask:source.behindMask?structuredClone(source.behindMask):Array.from({length:source.h},(_,y)=>Array(source.w).fill(y<source.h-1?1:0))};let mode='open',paint=0,customOpen=source.openAssetId?await imageAsset(source.openAssetId):null;
 if(!source.id){for(let y=0;y<source.h;y++)for(let x=0;x<source.w;x++){draft.closedMask[y][x]=1;draft.openMask[y][x]=1;draft.interactionMask[y][x]=0;draft.behindMask[y][x]=0;}const x=Math.floor(source.w/2),y=Math.floor(source.h/2);draft.openMask[y][x]=0;draft.interactionMask[y][x]=1;}
 api.modal('Gate artwork & passage',`<label>Name<input id="customGateName" maxlength="80" value="${esc(source.name+(source.id&&!api.library.has('gateStyles',source.id)?' copy':''))}"></label><label>Orientation<select id="customGateAxis"><option value="horizontal" ${source.orientation!=='vertical'?'selected':''}>Horizontal fence · walk north/south</option><option value="vertical" ${source.orientation==='vertical'?'selected':''}>Vertical fence · walk east/west</option><option value="custom">Custom shape</option></select></label><div class="gate-preview-pair"><div><b>Closed</b><canvas id="gateClosedPreview"></canvas></div><div><b>Open</b><canvas id="gateOpenPreview"></canvas></div></div><div class="smart-tabs">${[['closed','Closed walking'],['open','Open walking'],['interact','Press A'],['behind','Above player']].map(([id,n])=>`<button type="button" data-gate-mode="${id}">${n}</button>`).join('')}</div><div class="smart-actions" id="gateMaskBrush"><button type="button" data-gate-brush="1">Solid</button><button type="button" data-gate-brush="0">Walk</button><button type="button" data-gate-brush="null">Keep ground</button></div><div id="gateMaskGrid" class="gate-mask-grid" style="--cols:${source.w}"></div><p id="gateMaskHelp" class="hint-line"></p><div class="smart-actions"><button id="gateAutoPassage" type="button">Set centre opening</button><button id="gateUploadOpen" type="button">Upload open-state PNG</button><button id="gateClearOpen" type="button">Generate open art from passage</button></div><input id="gateOpenFile" type="file" accept="image/png" hidden><label class="check"><input id="gateRemoveWalls" type="checkbox" ${source.replaceWalls!==false?'checked':''}> Replace wall-brush cells underneath when placed</label><p>Green = walkable, red = solid, grey = keep ground. The open image removes marked panels and keeps supports. A cells must touch the opening. Gates reset when the map reloads.</p>`,async()=>{draft.name=$('#customGateName').value.trim()||'My gate';draft.orientation=$('#customGateAxis').value;draft.replaceWalls=$('#gateRemoveWalls').checked;let anchor=null;for(let y=0;y<draft.h&&!anchor;y++)for(let x=0;x<draft.w;x++)if(draft.openMask[y][x]===0&&draft.closedMask[y][x]===1){anchor={x,y};break;}draft.placementAnchor=anchor;validateGateMasks(draft);const opened=makeOpen(),a={id:spriteId(),name:draft.name+' closed',width:closed.width,height:closed.height,tileSize:16,data:closed.toDataURL('image/png'),category:'My gate artwork'},b={...a,id:spriteId(),name:draft.name+' open',data:opened.toDataURL('image/png')};draft.closedAssetId=a.id;draft.openAssetId=b.id;await api.library.save('gateStyles',draft,api.asset,[a,b]);api.change(()=>{api.library.attach(api.project(),'gateStyles',draft);if(placed){const{x,y,id,text}=placed;Object.assign(placed,structuredClone(draft),{x,y,id,text});}});api.saved(draft,placed);api.toast(placed?'Placed gate updated; reusable template saved.':'Gate saved across projects. Tap its opening tile to place it.');},placed?'Update gate & save template':'Save reusable gate');
 function makeOpen(){const c=document.createElement('canvas');c.width=closed.width;c.height=closed.height;const cx=c.getContext('2d');cx.drawImage(customOpen||closed,0,0,c.width,c.height);if(!customOpen)for(let y=0;y<draft.h;y++)for(let x=0;x<draft.w;x++)if(draft.openMask[y][x]===0&&draft.closedMask[y][x]!==0)cx.clearRect(x*16,y*16,16,16);return c;}
 function previews(){for(const[id,canvas]of[['gateClosedPreview',closed],['gateOpenPreview',makeOpen()]]){const c=$('#'+id);c.width=canvas.width;c.height=canvas.height;c.getContext('2d').drawImage(canvas,0,0);}}
 function grid(){const data=mode==='closed'?draft.closedMask:mode==='open'?draft.openMask:mode==='interact'?draft.interactionMask:draft.behindMask;$('#gateMaskBrush').hidden=['interact','behind'].includes(mode);$('#gateMaskHelp').textContent=mode==='interact'?'Tap to mark the cells the player can face and press A on.':mode==='behind'?'Tap artwork cells that should cover a player walking behind them.':'Choose Solid, Walk or Keep ground, then tap cells.';$('#gateMaskGrid').innerHTML=data.map((row,y)=>row.map((value,x)=>`<button type="button" data-gate-cell="${x},${y}" class="gate-cell ${['interact','behind'].includes(mode)?value?'interaction':'keep':value===1?'solid':value===0?'walk':'keep'}" aria-label="${x+1},${y+1}: ${mode} ${String(value)}">${mode==='interact'&&value?'A':mode==='behind'&&value?'↑':value===1?'×':value===0?'○':'·'}</button>`).join('')).join('');document.querySelectorAll('[data-gate-cell]').forEach(b=>b.onclick=()=>{const[x,y]=b.dataset.gateCell.split(',').map(Number);data[y][x]=['interact','behind'].includes(mode)?data[y][x]?0:1:paint;grid();previews();});document.querySelectorAll('[data-gate-mode]').forEach(b=>b.classList.toggle('active',b.dataset.gateMode===mode));document.querySelectorAll('[data-gate-brush]').forEach(b=>b.classList.toggle('active',b.dataset.gateBrush===String(paint)));}
 document.querySelectorAll('[data-gate-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.gateMode;grid();});document.querySelectorAll('[data-gate-brush]').forEach(b=>b.onclick=()=>{paint=b.dataset.gateBrush==='null'?null:+b.dataset.gateBrush;grid();});$('#gateAutoPassage').onclick=()=>{const axis=$('#customGateAxis').value;for(let y=0;y<draft.h;y++)for(let x=0;x<draft.w;x++){const opening=axis==='vertical'?y===Math.floor(draft.h/2):x===Math.floor(draft.w/2);draft.closedMask[y][x]=1;draft.openMask[y][x]=opening?0:1;draft.interactionMask[y][x]=opening?1:0;draft.behindMask[y][x]=0;}customOpen=null;grid();previews();};$('#gateUploadOpen').onclick=()=>$('#gateOpenFile').click();$('#gateOpenFile').onchange=async e=>{try{const file=e.target.files?.[0];if(!file)return;if(file.size>2e6)throw Error('Use an open-state PNG under 2 MB.');const data=await new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(f.result);f.onerror=reject;f.readAsDataURL(file);});const image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=data;});if(image.width!==closed.width||image.height!==closed.height)throw Error('Use a '+closed.width+' × '+closed.height+' image.');customOpen=image;previews();}catch(e){api.error(e);}e.target.value='';};$('#gateClearOpen').onclick=()=>{customOpen=null;previews();};grid();previews();}
 return{open,edit};
}
